const body = $input.item.json.body || $input.item.json;
return {
  prompt: body.prompt || 'Sin consulta',
  contexto: body.contexto || null,
  evento_id: body.evento_id
};

const gptResponse = $json;
const content = gptResponse.choices && gptResponse.choices[0] && gptResponse.choices[0].message
  ? gptResponse.choices[0].message.content
  : 'No se pudo obtener respuesta de la IA.';
return {
  success: true,
  respuesta: content,
  modelo: 'gpt-4o',
  timestamp: new Date().toISOString()
};
